function scrollToSection(selector) {
 if(selector==='.app-page-title')window.scrollTo?.({top:0,behavior:'instant'});
 const section=document.querySelector(selector);
 if(!section)return;
 for(let parent=section;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
 section.scrollIntoView({behavior:'instant',block:'start'});
 const heading=section.querySelector('h1,h2,h3')??section;
 heading.setAttribute('tabindex','-1');
 heading.focus({preventScroll:true});
}
