const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,positive=false)=>`<bdi class="money" dir="ltr">${positive&&n>0?'+':''}${esc(currency(n))}</bdi>`;
let noticeTimer,accountEmail='',accountId='';
let refreshView=null,refreshLeaving=false;
try{
 const saved=JSON.parse(sessionStorage.getItem('monthly-flow-refresh-view')||'null');
 sessionStorage.removeItem('monthly-flow-refresh-view');
 if(saved&&['progress','goals','purchase','monthly','forecast','plans','settings','details','detail-management','manual'].includes(saved.tab)&&/^20[0-9]{2}-(0[1-9]|1[0-2])$/.test(saved.selectedMonth)){refreshView=saved;tab=saved.tab;}
}catch{}

function defaultViewMonth(value){return tab==='details'?latestExpenseDataMonth(value,todayMonth()):defaultBudgetMonth(value,todayMonth());}
function notify(text){const node=document.getElementById('notice');node.textContent=text;node.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>node.classList.remove('visible'),6500);}
function nfield(label,name,value,min=0,max=100000000){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="number" dir="ltr" inputmode="decimal" min="${min}" max="${max}" step="0.01" value="" data-current="${esc(value)}" placeholder="${esc(value)}"></label>`;}
function tfield(label,name,value,hint=''){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="text" dir="auto" maxlength="100" value="" data-current="${esc(value)}" placeholder="${esc(value||hint)}"></label>`;}
function mfield(label,name,value,min=plan.startMonth,max=monthAt(plan.startMonth,96)){
 const [year,month]=value.split('-'),start=readNumber(min.slice(0,4)),end=readNumber(max.slice(0,4));
 const months=Array.from({length:12},(_,i)=>{const number=String(i+1).padStart(2,'0');const text=new Intl.DateTimeFormat('he-IL',{month:'long',timeZone:'UTC'}).format(new Date(`2026-${number}-01T12:00:00Z`));return `<option value="${number}" ${number===month?'selected':''}>${text}</option>`;}).join('');
 const years=Array.from({length:end-start+1},(_,i)=>`<option value="${start+i}" ${String(start+i)===year?'selected':''}>${start+i}</option>`).join('');
 return `<div class="field"><span>${esc(label)}</span><div class="month-picker" data-name="${esc(name)}" data-min="${min}" data-max="${max}"><select data-date-part="month" aria-label="${esc(label)} — חודש">${months}</select><select data-date-part="year" aria-label="${esc(label)} — שנה">${years}</select><input type="hidden" name="${esc(name)}" value="${value}"></div></div>`;
}

function select(label,name,items,value){return `<label class="field">${esc(label)}<select name="${name}">${items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function candidate(payments){return {id:'candidate-purchase',name:purchase.name.trim()||'רכישה חדשה',amount:purchase.amount,fees:purchase.fees,firstMonth:purchase.firstMonth,payments,source:'direct',kind:'expense',...(purchase.cashAccountId?{cashAccountId:purchase.cashAccountId}:{}),...(purchase.cardId?{cardId:purchase.cardId}:{})};}
function validPurchase(){const test={...plan,expenses:[...plan.expenses,candidate(24)]};return validatePlan(test);}
function options(){if(!validPurchase())return[];const horizon=Math.max(plan.horizon,indexMonth(purchase.firstMonth)-indexMonth(plan.startMonth)+24);return [1,3,6,12,24].map(count=>{const item=candidate(count),rows=forecast(plan,item,horizon),low=scenarioAssessment(rows,todayMonth());return {count,item,rows,low,above:cashAccountList(plan).length?cashScenarioSafe({...plan,expenses:[...plan.expenses,item]},[item.id],todayMonth()):!!low&&low.balance>=plan.buffer};});}
function chart(base,trial){const rows=base,values=[plan.opening,plan.buffer,...base.map(r=>r.balance),...(trial||[]).map(r=>r.balance)],min=Math.min(...values),max=Math.max(...values),span=Math.max(max-min,1000),y=v=>220-((v-min)/span)*180,x=i=>960-i/Math.max(1,rows.length-1)*860,path=r=>r.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v.balance).toFixed(1)}`).join(' '),ticks=Array.from({length:5},(_,i)=>min+span*i/4),indices=[...new Set([0,Math.floor((rows.length-1)/3),Math.floor(2*(rows.length-1)/3),rows.length-1])];return `<svg class="chart" viewBox="0 0 1000 280" role="img" aria-label="תחזית יתרה בסוף החודש, בשקלים. הזמן מתקדם מימין לשמאל. הקו הסגול הוא התכנון הנוכחי, הטורקיז כולל את התרחיש, והקו המקווקו הוא יתרת הביטחון.">${ticks.map(v=>`<line x1="100" x2="960" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="85" y="${y(v)+5}" text-anchor="end" direction="ltr" fill="var(--muted)" font-size="15">${esc(new Intl.NumberFormat('he-IL',{maximumFractionDigits:0}).format(v))}</text>`).join('')}<text x="85" y="23" text-anchor="end" fill="var(--muted)" font-size="15">₪</text><line x1="100" y1="${y(plan.buffer)}" x2="960" y2="${y(plan.buffer)}" stroke="var(--amber)" stroke-width="1.5" stroke-dasharray="7 6"/><path d="${path(base)}" stroke="var(--accent)" stroke-width="3" fill="none"/>${trial?`<path d="${path(trial)}" stroke="var(--teal)" stroke-width="3" fill="none"/>`:''}${indices.map(i=>`<text x="${x(i)}" y="257" text-anchor="middle" fill="var(--muted)" font-size="16">${esc(monthLabel(rows[i].month))}</text>`).join('')}</svg><p class="help">יתרות סוף חודש בשקלים; הזמן מתקדם מימין לשמאל. הקו המקווקו הוא יתרת הביטחון. היתרה אינה מתארת את מצב החשבון בכל יום בתוך החודש.</p>`;}

function forecastPanel(rows,trial){return `<section class="panel"><div class="section-heading"><h2>תחזית היתרה</h2><span class="muted">${rows.length} חודשים</span></div>${chart(rows,trial)}<div class="chart-labels"><span>${monthLabel(rows[0].month)}</span><span>${monthLabel(rows.at(-1).month)}</span></div><div class="legend"><span>התכנון הנוכחי</span>${trial?'<span class="trial">עם התרחיש</span>':''}<span class="buffer">יתרת ביטחון</span></div></section>`;}
