 for(const category of root.querySelectorAll('[data-settings-category]')){const key=category.dataset.settingsCategory;category.open=states?.get(key)??false;[...category.querySelectorAll('details')].forEach((node,i)=>{if(states?.has(key+'/'+i))node.open=states.get(key+'/'+i);});if(key==='budgets'&&joinToken||key==='privacy'&&(securitySetup||encryptedImport||securityError))category.open=true;}
