function periodSummary(rows){const period=rows.slice(0,7),sum=key=>period.reduce((total,row)=>total+cents(row[key]),0)/100;return `<section class="panel"><div class="section-heading"><h2>סיכום התקופה</h2><span class="muted">${monthLabel(period[0].month)} – ${monthLabel(period.at(-1).month)}</span></div><div class="month-result"><div><span>הכנסות מצטברות</span><strong>${money(sum('income'))}</strong></div>${sum('incomingTransfers')?`<div><span>העברות נכנסות</span><strong>${money(sum('incomingTransfers'))}</strong></div>`:''}${sum('outgoingTransfers')?`<div><span>העברות יוצאות פנימיות</span><strong>${money(sum('outgoingTransfers'))}</strong></div>`:''}<div><span>הוצאות מצטברות</span><strong>${money(sum('spending'))}</strong></div><div><span>חיסכון והשקעות מצטברים</span><strong>${money(sum('saving'))}</strong></div><div><span>פריטים מתוכננים, נטו</span><strong>${money(sum('planned'))}</strong></div><div><span>תזרים נטו מצטבר</span><strong>${money(sum('net'))}</strong></div><div><span>יתרה בסוף התקופה</span><strong>${money(period.at(-1).balance)}</strong></div></div><p class="help">יתרה התחלתית ${money(plan.opening)} + תזרים נטו מצטבר ${money(sum('net'))} = יתרה בסוף התקופה ${money(period.at(-1).balance)}. בכל חודש היתרה ממשיכה מהחודש הקודם. פריטים מתוכננים כוללים הוצאות בניכוי הכנסות חד־פעמיות.</p></section>`;}
