function contextHelp(key){
 const topics={
  scenario:['בדיקת תרחיש רכישות','שדות שלא שיניתם שומרים על הערך המוצג. מזינים את מחיר העסקה כפי שיופיע בחיוב, כולל עלויות שכבר חושבו בחנות. התשלום הראשון מתחיל החודש; אפשר לשנות חודש ואופן תשלום באפשרויות המתקדמות. ההמלצה נבדקת מהחודש הנוכחי, כשיתר הפריטים נשארים כפי שהגדרתם. פריט חדש בכרטיס מוצג כהוצאה נוספת בתרחיש; לאחר החלה, סימון בחודש שהחיוב כבר כולל תשלומים מתוכננים מונע ספירה כפולה. ביטול סימון של פריט קיים מדמה את הסרתו; לפני ההחלה יוצג סיכום השינויים. יש לשמור את התקציב לאחר ההחלה.'],
  monthly:['דיווח חודשי','שדה שלא שונה משתמש בסכום המוצג. בשמירה בוחרים דיווח בפועל או הערכה. שינוי משכורת מעדכן הערכות עתידיות בלבד.'],
  offcard:['הוצאות מחוץ לכרטיסים','מזומן, העברות והוראות קבע ששימשו לתשלום הוצאות. אין לכלול חיובי כרטיסים, צ׳קים, הפקדות לחסכון או העברות בין החשבונות שלכם.'],
  cheques:['צ׳קים והסך החודשי','צ׳ק שמסומן ״נפרד״ מתווסף בחודש הפירעון. אם כבר ספרתם אותו בסך הצ׳קים לחודש, סמנו אותו ״כלול״. סימון כנפרע לא מחייב שוב; ביטול צ׳ק כלול אינו משנה את הסך שהוזן.'],
  cardplanned:['תשלומים מתוכננים בכרטיס','אם הזנתם את החיוב המלא של הכרטיס, סמנו שהתשלומים כלולים. לדוגמה: חיוב של 5,000 ₪ הכולל תשלום מתוכנן של 500 ₪ נשאר 5,000 ₪; כשהוא לא כלול, החישוב הוא 5,500 ₪. הבחירה חלה על כל הכרטיסים בחודש זה.'],
  investment:['נתוני מחשבון ההשקעות','סכום התחלתי ריק משתמש בהפקדות להשקעה שדווחו בפועל, ללא תשואה. ממוצע חודשי משנה רק את הסימולציה. המחשבון אינו קורא יתרת תיק; הצפי אינו מבטיח תשואה.'],
  goals:['יעדים חודשיים','יעדי החסכון וההשקעה משמשים להשוואה מול ההפקדות; הם אינם מעבירים כסף או משנים את התחזית. אפס משאיר יעד לא מוגדר.']
 };return topics[key];
}
