function mutate(next,message){if(typeof budgetMeta==='function'&&budgetMeta().role==='viewer'){notify('התקציב פתוח לצפייה בלבד.');return false;}if(!validatePlan(next)){notify('יש לבדוק את הסכומים והתאריכים. פריטים מתוכננים צריכים להתחיל בתקופת התחזית ולהסתיים בתוך עשר שנים.');render();return false;}if(typeof saveDockAccepted==='function')saveDockAccepted();const before=achievements(plan,selectedMonth,todayMonth()),after=achievements(next,selectedMonth,todayMonth());const changed=JSON.stringify(next)!==JSON.stringify(plan);plan=next;dirty=typeof draftSavedSnapshot!=='undefined'&&draftSavedSnapshot?JSON.stringify(plan)!==draftSavedSnapshot:dirty||changed;render();if(!monthlyPending&&after.some(k=>!before.includes(k))){notify('כל הכבוד! הגעת להישג חדש החודש. יש לשמור את התקציב.');document.querySelector('.goal-grid')?.classList.add('celebrate');}if(message)notify(message);return true;}
