// Pull-down refresh: start at the document top and avoid controls or nested scrollers.
let pullStart=null,pullX=null,pullDistance=0;
const pullIndicator=document.getElementById('pull-refresh-indicator');
function resetPull(){pullStart=null;pullX=null;pullDistance=0;if(!loading)pullIndicator.hidden=true;}
document.addEventListener('touchstart',event=>{
 resetPull();
 if(event.touches.length!==1||loading||saving||(document.scrollingElement?.scrollTop??0)>2||document.querySelector('dialog[open]'))return;
 if(event.target.closest?.('input,select,textarea,button,a,summary,[role=button],[role=slider],[contenteditable]'))return;
 const touch=event.touches[0];if(touch.clientY<0||touch.clientY>window.innerHeight/3)return;
 for(let node=event.target;node;node=node.parentElement){if(node!==document.scrollingElement&&node!==document.body&&node!==document.documentElement&&node.scrollHeight>node.clientHeight+2)return;}
 pullStart=touch.clientY;pullX=touch.clientX;
},{passive:true});
document.addEventListener('touchmove',event=>{
 if(event.touches.length!==1){resetPull();return;}if(pullStart===null)return;
 const touch=event.touches[0];pullDistance=touch.clientY-pullStart;
 const horizontal=Math.abs(touch.clientX-pullX);
 // Ignore initial finger jitter; only commit after a clear downward gesture.
 if(pullDistance<-12||(horizontal>12&&horizontal>pullDistance)||(document.scrollingElement?.scrollTop??0)>2||document.querySelector('dialog[open]')){resetPull();return;}
 if(pullDistance<=12)return;if(!event.cancelable){resetPull();return;}event.preventDefault();
 pullIndicator.hidden=false;pullIndicator.textContent=pullDistance>=80?'אפשר לשחרר כדי לרענן':'משיכה מטה לרענון';
},{passive:false});
document.addEventListener('touchend',()=>{const shouldRefresh=pullStart!==null&&pullDistance>=80&&!document.querySelector('dialog[open]');resetPull();if(shouldRefresh)refreshBudget();});
document.addEventListener('touchcancel',resetPull);


function chartNavigation(){const mode=typeof chartMode==='undefined'?'flow':chartMode;return `<div class="actions chart-navigation"><button class="btn ${tab==='forecast'&&mode==='reports'?'primary':''}" data-action="tab" data-tab="forecast" data-chart-mode="reports" aria-pressed="${tab==='forecast'&&mode==='reports'}">נתונים</button><button class="btn ${tab==='forecast'&&mode==='flow'?'primary':''}" data-action="tab" data-tab="forecast" data-chart-mode="flow" aria-pressed="${tab==='forecast'&&mode==='flow'}">תחזית עו״ש</button></div>`;}

function appMenuLink(label,attributes,symbol='settings'){return `<button class="btn app-menu-row" ${attributes}><span class="app-menu-row-icon" aria-hidden="true">${icon(symbol)}</span><span>${label}</span><span class="app-menu-chevron" aria-hidden="true">‹</span></button>`;}
function appMenuSectionLink(section,symbol='settings'){return appMenuLink(settingsTitles[section],`data-action="tab" data-tab="settings" data-settings-section="${section}"`,symbol);}
function manualEntryLink(title,description,attributes){return `<button class="manual-entry" type="button" ${attributes}><span><strong>${title}</strong><small>${description}</small></span><span aria-hidden="true">‹</span></button>`;}
function manualEntryView(){
 const month=(section)=>`data-action="tab" data-tab="monthly" data-section="${section}"`,settings=(section)=>`data-action="tab" data-tab="settings" data-settings-section="${section}"`;
 return `<div class="manual-entry-hub"><section class="panel manual-entry-intro"><p>להזנה שוטפת, מעלים דוחות במרכז הדוחות. כאן אפשר להשלים ולתקן נתונים ידנית.</p><button class="btn primary" data-action="report-inbox">פתיחת מרכז הדוחות</button></section><div class="manual-entry-groups"><section class="panel"><h2>הכנסות והוצאות</h2>${manualEntryLink('משכורת והכנסות נוספות','עדכון הסכומים של החודש הנבחר',month('monthly-income'))}${manualEntryLink('חיובי כרטיסים והוצאות אחרות','סכומים חודשיים שלא הושלמו דרך הדוחות',month('monthly-expense'))}${manualEntryLink('יתרת עו״ש בפועל','היתרה כפי שמופיעה בבנק',month('bank-balance'))}${manualEntryLink('פירוט וסיווג הוצאות','הוספה, תיקון קטגוריות ותקרות הוצאה','data-action="tab" data-tab="detail-management" data-section="breakdown"')}</section><section class="panel"><h2>צ׳קים ותשלומים מתוכננים</h2>${manualEntryLink('רשימת הצ׳קים','הוספה, מועד פירעון ומצב הצ׳ק','data-action="tab" data-tab="detail-management" data-section="cheques"')}${manualEntryLink('הוצאות והכנסות עתידיות','רכישות, תשלומים ואירועים מתוכננים','data-action="tab" data-tab="plans" data-section="planned-items"')}${manualEntryLink('הלוואות והחזרים','סכום ההחזר והתקופה שנותרה','data-action="tab" data-tab="plans" data-section="loans"')}</section><section class="panel"><h2>חסכונות והשקעות</h2>${manualEntryLink('הפקדות שבוצעו החודש','חסכון והשקעות אישיים ומשותפים',month('monthly-future'))}${manualEntryLink('יתרות חסכון וחלוקה למטרות','עדכון היתרות והחלוקה של הכסף הקיים',settings('savings'))}${manualEntryLink('תכנון הפקדות חודשיות','סכומים מתוכננים ומועד תחילת ההפקדה',settings('savings'))}${typeof statusInsightsView==='function'?`<details class="manual-insights"><summary>מגמות בולטות ותכנון הפקדות</summary>${statusInsightsView()}</details>`:''}</section><section class="panel"><h2>חשבונות ובסיס התקציב</h2>${manualEntryLink('חשבונות הבנק','חשבונות משלמים, יתרות פתיחה ושיוך',settings('cash-accounts'))}${manualEntryLink('כרטיסי האשראי','הוספה, שמות כרטיסים ומועדי חיוב','data-action="cards-manage"')}${manualEntryLink('בסיס התחזית והיעדים','הערכות קבועות, יתרת ביטחון ויעדים',settings('budget'))}</section></div></div>`;
}
function appMenuView(){return `<dialog id="app-menu-dialog" class="app-menu-dialog" aria-labelledby="app-menu-title"><div class="app-menu-heading"><h2 id="app-menu-title">תפריט</h2><button class="btn" data-action="app-menu-close" aria-label="סגירת התפריט">×</button></div>${demoPreview?`<div class="budget-context"><strong>דוגמה · לא הנתונים שלך</strong><a class="btn" href="/">חזרה לתקציב שלי</a></div>`:budgetSwitcher(true)}${plan.demo&&!demoPreview?`<div class="banner"><span>תקציב לדוגמה · הסכומים להמחשה בלבד.</span><button class="btn" data-action="fresh" ${!loaded?'disabled':''}>הזנת הנתונים שלי</button></div>`:''}<nav class="app-menu-links" aria-label="פעולות וניהול"><section class="app-menu-group" aria-labelledby="menu-activity"><h3 id="menu-activity">פעילות</h3>${appMenuLink('מרכז הדוחות',`data-action="report-inbox" ${!loaded||loading||saving?'disabled':''}`,'details')}${appMenuLink('הזנה ועריכה ידנית','data-action="tab" data-tab="manual"','monthly')}${appMenuSectionLink('bank-import','details')}</section><section class="app-menu-group" aria-labelledby="menu-app"><h3 id="menu-app">חשבון ואפליקציה</h3>${demoPreview?'':appMenuSectionLink('budgets','wallet')}${appMenuSectionLink('privacy')}${window.monthlyFlowStandalone&&typeof walletSettingsView==='function'?appMenuSectionLink('connections','purchase'):''}${appMenuSectionLink('profile')}${appMenuSectionLink('app')}${window.monthlyFlowAdmin?appMenuSectionLink('admin'):''}</section></nav><section class="app-menu-save" aria-label="שמירה ורענון"><div class="actions"><span class="save-status">${demoPreview?'מצב דוגמה · ללא שמירה':loading?'טוען…':saving?'שומר…':dirty?'שינויים שלא נשמרו':revision?'התקציב נשמר':'טרם נשמר'}</span><button class="btn refresh-button" data-action="refresh" aria-label="רענון האפליקציה" ${loading||saving?'disabled':''}><span aria-hidden="true">↻</span><span>רענון האפליקציה</span></button><button hidden class="btn primary" data-action="save" ${demoPreview||!loaded||loading||saving||(!dirty&&revision&&!(tab==='monthly'&&monthlyNeedsConfirmation()))?'disabled':''}>${saving?'שומר…':tab==='monthly'?'שמירת החודש':'שמירת התקציב'}</button>${window.monthlyFlowStandalone?'<button class="btn" data-action="standalone-logout">יציאה מהחשבון</button>':''}</div></section>${accountEmail?`<p class="help app-menu-account">מחובר כ־<bdi dir="ltr">${esc(accountEmail)}</bdi></p>`:''}<p class="help app-build-id">גרסת האפליקציה · <bdi dir="ltr">__BUILD_ID__</bdi></p></dialog>`;}
function appMenuAction(action,btn){
 const dialog=document.getElementById('app-menu-dialog');
 if(action==='standalone-logout'){if(!canSwitchBudget())return true;const form=document.createElement('form');form.method='POST';form.action='/auth/logout';document.body.append(form);form.submit();return true;}
 if(action==='app-menu-open'){if(!dialog)return true;document.activeElement?.blur();const current=document.getElementById('app-menu-dialog');current.showModal();current.oncancel=event=>{event.preventDefault();current.close();};return true;}
 if(action==='app-menu-close'){dialog?.close();return true;}
 if(action==='cards-manage'&&btn?.closest?.('#app-menu-dialog')&&(!guardMonthlyNavigation()||!guardSavingsDraft()||!guardDetailNavigation()||hasSecurityDraft())){notify('יש לשמור או לבטל את העריכה הפתוחה לפני ניהול כרטיסים.');return true;}
 if(btn?.closest?.('#app-menu-dialog'))dialog?.close();
 return false;
}

function standaloneAdminView(){return window.monthlyFlowAdmin?`<section class="panel"><p class="help">רק חשבונות שאושרו יכולים להיכנס. הוספת משתמש אינה משתפת איתו את התקציב שלך.</p><button class="btn" data-action="admin-access-load">פתיחת רשימת הגישה</button><div id="admin-access-body" aria-live="polite"></div></section>`:'';}
let adminAccessBusy=false,adminAccessRevision=0;
function drawAdminAccess(data,message=''){
 const body=document.getElementById('admin-access-body');if(!body)return;
 adminAccessRevision=data.revision;
 body.innerHTML=`<p role="status">${esc(message)}</p><ul>${data.entries.map(entry=>`<li><bdi dir="ltr">${esc(entry.email)}</bdi> ${entry.admin?'<span class="muted">מנהל</span>':`<button class="btn" data-action="admin-access-remove" data-email="${esc(entry.email)}" aria-label="הסרת ${esc(entry.email)}">הסרה</button>`}</li>`).join('')}</ul><label class="field">אימייל של משתמש נוסף<input id="admin-access-email" type="email" dir="ltr" autocomplete="off" maxlength="254"></label><button class="btn primary" data-action="admin-access-add">אישור גישה</button><button class="btn" data-action="admin-access-load">רענון הרשימה</button>`;
}
async function standaloneAdminAction(action,btn){
 if(!window.monthlyFlowAdmin||adminAccessBusy)return;
 let email='';
 if(action==='admin-access-add'){const input=document.getElementById('admin-access-email');if(!input?.value.trim()||!input.reportValidity())return;email=input.value.trim();}
 if(action==='admin-access-remove'){email=btn.dataset.email;if(!confirm('להסיר את הגישה של '+email+'? התקציב השמור לא יימחק.'))return;}
 adminAccessBusy=true;const section=btn.closest('section');section?.querySelectorAll('button').forEach(b=>b.disabled=true);
 try{
  const options=action==='admin-access-load'?{}:{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,action:action==='admin-access-add'?'add':'remove',revision:adminAccessRevision})};
  const result=await fetch('/api/admin/access',options),data=await result.json();if(!result.ok)throw Error(data.error||'לא ניתן לעדכן את הרשימה.');
  drawAdminAccess(data,action==='admin-access-load'?'':action==='admin-access-add'?'הגישה אושרה.':'הגישה הוסרה.');
 }catch(error){notify(error.message)}finally{adminAccessBusy=false;section?.querySelectorAll('button').forEach(b=>b.disabled=false);}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button?.dataset.action.startsWith('admin-access-'))standaloneAdminAction(button.dataset.action,button);});
